import bcrypt from "bcryptjs";

/**
 * Default bcrypt cost factor matching PostgreSQL pgcrypto `gen_salt('bf', 12)`
 * used during initial Docker admin seeding.
 */
export const BCRYPT_COST = 12;

export async function hashPassword(
  plainPassword: string,
  cost: number = BCRYPT_COST,
): Promise<string> {
  return bcrypt.hash(plainPassword, cost);
}

/**
 * Verifies a plaintext password against a bcrypt hash (`$2a$`, `$2b$`, or `$2y$`),
 * including hashes generated by PostgreSQL `pgcrypto` `crypt(..., gen_salt('bf', 12))`.
 */
export async function verifyPassword(
  plainPassword: string,
  passwordHash: string,
): Promise<boolean> {
  if (!plainPassword || !passwordHash) {
    return false;
  }
  return bcrypt.compare(plainPassword, passwordHash);
}
